  let ⟨z₀, h₀⟩ := Hinh
  let rec findLeast (lb : ℤ) : ℤ × Bool :=
    if h₀ lb then (lb, true)
    else findLeast (lb + 1)
  let (lb, _) := findLeast b
  show { lb // P lb ∧ ∀ (z : ℤ), P z → lb ≤ z }
  | _ => by
    refine ⟨lb, h₀ lb, fun z hz => le_trans (Hb z hz) (le_add_of_nonneg_left (by norm_num))⟩
